/**
 * n8n Code node — "Run Once for All Items".
 *
 *   TickerUniverse (HTTP: EODHD exchange-symbol-list, one call per venue) ─┐
 *   MyCurrentUniverse (Postgres: ticker, miss_count)                      ─┴─> THIS
 *     -> Filter (action != 'SUMMARY')
 *        -> Switch on `action`
 *             ADD          -> Add New Ticker sub-workflow
 *             CLEANUP      -> hard delete (junk instruments + ISIN dupes)
 *             MISS         -> UPDATE universe SET miss_count = miss_count + 1
 *             SEEN         -> UPDATE universe SET miss_count = 0
 *             DELIST       -> mark inactive (NOT delete — see EQR note)
 *             OUT_OF_SCOPE -> no-op / log
 *             REVIEW       -> no-op / log
 *
 * Requires:
 *   ALTER TABLE universe ADD COLUMN IF NOT EXISTS miss_count integer NOT NULL DEFAULT 0;
 * and MyCurrentUniverse must SELECT it, UNFILTERED (no WHERE is_delisted / type
 * clause — anything the query hides looks absent and re-queues as an ADD forever).
 *
 * Design notes, each earned the hard way:
 *
 *  - The feed tags EVERY row "Common Stock", so Type carries no signal.
 *    Instrument class is inferred from the code.
 *  - Absence from one pull is not evidence of delisting. A ticker must be
 *    missing MISS_THRESHOLD consecutive runs before it is even proposed.
 *  - EQR (Equity Residential, S&P 500, ~$25bn) is simply absent from EODHD's
 *    NYSE list — alphabetical continuity around it is intact, so it is a
 *    vendor hole, not truncation. This feed is never the sole authority for
 *    deletion. Mark inactive; do not DELETE.
 *  - A shared ISIN only means "same security" when the codes are suffix
 *    variants. EODHD emits wrong ISINs shared by unrelated companies
 *    (ALBT/CHGA, BSIN/USEG, GAMB/GRSD); collapsing those destroys a listing.
 *  - Deduped is not absent. Dedupe losers go to CLEANUP, never to MISS.
 *  - BATS rows often carry Name === Code and are largely leveraged ETNs.
 *    No name means nothing to filter on, so it is never safe to auto-ingest.
 */

// ---------------------------------------------------------------- config ----

const EXCHANGE_NODE = 'Loop Over Items2';
const UNIVERSE_NODE = 'MyCurrentUniverse';

// Venues I screen. NYSE returns NYSE ARCA and a ~16-row NYSE MKT stub, which
// is why AMEX is called separately upstream. ARCA is deliberately absent: it
// is overwhelmingly ETFs, and ARCA holdings are parked, never deleted.

const ACCEPTED_EXCHANGES = new Set(['NYSE', 'NASDAQ', 'NYSE MKT', 'AMEX', 'BATS', 'LSE']);

// Per-venue floor. A single total is useless across a multi-call pull: NASDAQ
// alone clears any global minimum while a silently failed AMEX call sends
// every NYSE American holding into the miss counter.
// Set these from the FIRST successful run's rows_by_exchange, not from guesses.
const MIN_ROWS_PER_EXCHANGE = {
  'NYSE': 2000,
  'NASDAQ': 3000,
  'BATS': 20,
  'AMEX': 200,   // NYSE American, own call — returned 259
  // 'NYSE MKT' has no floor: it is a ~16-row stub that leaks in via the NYSE
  // call. Those rows are still accepted (it stays in ACCEPTED_EXCHANGES),
  // there is just no minimum to enforce on a venue nothing calls directly.
};

const MIN_EXCHANGE_ROWS = 1000;   // global backstop

// Consecutive absent runs before a ticker is proposed for delisting.
const MISS_THRESHOLD = 5;

// Floor on threshold-crossers only. Should almost never fire.
const MAX_DELISTS_ABS = 40;
const MAX_DELISTS_PCT = 1;

const TICKER_FIELDS = ['ticker', 'Ticker', 'symbol', 'Symbol', 'code', 'Code'];
const MISS_FIELDS = ['miss_count', 'missCount', 'misses'];

// ------------------------------------------------------------- filtering ----

// Hyphenated non-common classes. Class shares (-A, -B) are NOT here:
// BRK-B, GEF-B, BF-B, AGM-A, CWEN-A are common stock.
const NON_COMMON_SUFFIX = /-(WT|WS|W|WI|RW|R|RI|U|UN|P|PR)(-[A-Z0-9]+)?$/;
const PREFERRED_SUFFIX  = /-P[A-Z]$/;
const FIVE_LETTER_PFD   = /^[A-Z]{4}[OPLMNZ]$/;
const TEST_CODE         = /^(Z[A-Z]ZZT|N?TEST(-[A-Z])?|PTEST(-[A-Z])?)$/;
const TEST_NAME = /Tick Pilot|Test Control|TEST STOCK/i;



// AILEQ/MMATQ (bankruptcy stubs) are indistinguishable by code from AMBIQ
// (Ambipar, live NYSE). Ambiguous -> REVIEW, never a silent exclusion.
const MAYBE_BANKRUPT = /^[A-Z]{4,}Q$/;

// NASDAQ appends a 5th letter with no hyphen. Only a derivative when the
// stripped base is itself in the feed — that check is what stops this eating
// legitimate five-letter tickers.
const NASDAQ_DERIV_SUFFIX = [
  { re: /^([A-Z]{2,4})WW$/, reason: 'warrant' },
  { re: /^([A-Z]{3,4})W$/,  reason: 'warrant' },
  { re: /^([A-Z]{3,4})R$/,  reason: 'rights'  },
  { re: /^([A-Z]{3,4})U$/,  reason: 'unit'    },
  { re: /^([A-Z]{2,4})UN$/, reason: 'unit'    },
];

const FUND_NAME = new RegExp([
  'ETF', 'Exchange[- ]Traded Fund', 'ProShares', 'iShares', 'Direxion',
  'Bitwise', 'Teucrium', 'Sprott Physical', 'FundVantage', 'Series Trust',
  'Investment Dimensions', 'Listed Funds Trust', 'Timothy Plan',
  'Advisor Managed Portfolios', 'Closed Fund', 'Municipal Income',
  'Term Trust', 'Zacks Trust', 'MicroSectors', 'Covington Trust',
].join('|'), 'i');

const SPAC_NAME = /Acquisition (Corp|Company|Corporation|Limited|Ltd)|Merger Corp|Capital Corp\b/i;

// ------------------------------------------------------------- utilities ----

/** Normalise to the hyphen form used in Postgres (GEF-B, not GEF.B / GEF B). */
function normaliseTicker(raw) {
  if (raw === null || raw === undefined) return null;
  const t = String(raw).trim().toUpperCase().replace(/[.\s]/g, '-');
  return t || null;
}

function pickField(json, fields) {
  if (!json || typeof json !== 'object') return null;
  for (const f of fields) {
    if (json[f] !== undefined && json[f] !== null && json[f] !== '') return json[f];
  }
  return null;
}

function readNode(nodeName) {
  let items;
  try {
    items = $(nodeName).all();
  } catch (e) {
    throw new Error(
      `Cannot reach node "${nodeName}". Check the name matches exactly ` +
      `(case sensitive) and that the node ran in this execution.`
    );
  }
  const rows = [];
  for (const item of items) {
    const json = item.json;
    if (Array.isArray(json)) {
      for (const r of json) if (r && typeof r === 'object') rows.push(r);
    } else if (json && typeof json === 'object') {
      const vals = Object.values(json);
      if (vals.length === 1 && Array.isArray(vals[0])) {
        for (const r of vals[0]) if (r && typeof r === 'object') rows.push(r);
      } else {
        rows.push(json);
      }
    }
  }
  return rows;
}

/** Code-only classification. Works on my universe rows, which carry no Name. */
function classifyCode(code) {
  if (!code)                        return { keep: false, reason: 'no_code' };
  if (TEST_CODE.test(code))         return { keep: false, reason: 'test_symbol' };
  if (NON_COMMON_SUFFIX.test(code)) return { keep: false, reason: 'warrant_right_or_unit' };
  if (PREFERRED_SUFFIX.test(code))  return { keep: false, reason: 'preferred_series' };
  if (FIVE_LETTER_PFD.test(code))   return { review: true, reason: 'maybe_preferred_series' };
  if (MAYBE_BANKRUPT.test(code))    return { review: true, reason: 'maybe_bankruptcy_stub' };
  return { keep: true };
}

/** Un-hyphenated NASDAQ derivative whose base trades in the feed? */
function derivativeOf(code, allCodes) {
  for (const { re, reason } of NASDAQ_DERIV_SUFFIX) {
    const m = re.exec(code);
    if (m && allCodes.has(m[1])) return `${reason}_of_${m[1]}`;
  }
  return null;
}

/** Full classification for one exchange row (code + name + exchange). */
function classifyRow(row) {
  const code = normaliseTicker(row.Code);
  const name = typeof row.Name === 'string' ? row.Name.trim() : '';
  const exch = typeof row.Exchange === 'string' ? row.Exchange.trim() : '';
  if (code && /^[0-9]/.test(code)) {
    return { outOfScope: true, reason: 'foreign_listing_digit_code' };
  }
  if (!ACCEPTED_EXCHANGES.has(exch)) {
    return { outOfScope: true, reason: `exchange_${exch || 'unknown'}` };
  }

  const byCode = classifyCode(code);

  // FIVE_LETTER_PFD only means preferred when the name backs it up; plenty of
  // ordinary NASDAQ tickers are five letters ending in those characters.
  if (byCode.review && byCode.reason === 'maybe_preferred_series') {
    if (TEST_NAME.test(name)) return { keep: false, reason: 'test_symbol' };
    if (FUND_NAME.test(name)) return { keep: false, reason: 'preferred_series' };
    return { keep: true };
  }
  if (!byCode.keep) return byCode;

  if (FUND_NAME.test(name)) return { review: true, reason: 'looks_like_fund' };
  if (SPAC_NAME.test(name)) return { review: true, reason: 'looks_like_spac' };

  // ...in classifyRow, replacing the single no-name check:
  if (!name || name === code) {
    // BATS nameless rows are overwhelmingly leveraged ETNs — park and forget.
    // AMEX/NYSE MKT nameless rows are more likely real small caps with a thin
    // vendor record, and are worth a manual look or a second-source lookup.
    return {
      review: true,
      reason: exch === 'BATS' ? 'no_name_bats_likely_etn' : 'no_name_needs_lookup',
    };
  }
  return byCode;
}

/** Are two codes plausibly the same instrument (suffix variants)? */
function sameSecurity(a, b) {
  const bare = (s) => s.replace(/-/g, '');
  const x = bare(a);
  const y = bare(b);
  return x.startsWith(y) || y.startsWith(x);
}

// ------------------------------------------------------------------ main ----

const exchangeRows = readNode(EXCHANGE_NODE);
const universeRows = readNode(UNIVERSE_NODE);

const seenByExchange = exchangeRows.reduce((a, r) => {
  const e = (typeof r.Exchange === 'string' ? r.Exchange.trim() : '') || '(blank)';
  a[e] = (a[e] || 0) + 1;
  return a;
}, {});

// -- Feed completeness (per-venue) ------------------------------------------
// A venue below its floor means an incomplete pull: API hiccup, truncated body,
// or a market holiday when that venue serves no symbols. Do NOT throw, and do
// NOT let it drive miss/delist (that would flag every ticker on the missing
// venue as absent and march it toward DELIST). But ADDs are always safe — a
// ticker PRESENT in the feed exists — so a closed venue must never block adding
// tickers from the venues that DID return. Record the shortfall; downstream we
// suppress only the destructive direction, never ADDs.
const shortfalls = [];
if (exchangeRows.length < MIN_EXCHANGE_ROWS) {
  shortfalls.push(`TOTAL ${exchangeRows.length}/${MIN_EXCHANGE_ROWS}`);
}
for (const [exch, min] of Object.entries(MIN_ROWS_PER_EXCHANGE)) {
  const got = seenByExchange[exch] || 0;
  if (got < min) shortfalls.push(`${exch} ${got}/${min}`);
}
const feedComplete = shortfalls.length === 0;

if (universeRows.length === 0) {
  throw new Error(
    `${UNIVERSE_NODE} returned 0 rows. Query failed or the table is empty; ` +
    `either would queue the entire exchange as ADDs. Aborting.`
  );
}

// ticker -> current miss_count
const mine = new Map();
for (const row of universeRows) {
  const t = normaliseTicker(pickField(row, TICKER_FIELDS));
  if (!t) continue;
  const m = Number(pickField(row, MISS_FIELDS));
  mine.set(t, Number.isFinite(m) ? m : 0);
}

// EVERY code in the feed, all venues, all instrument classes. This is what
// distinguishes "I don't screen it" from "it no longer exists anywhere".
const allCodes = new Set();
for (const row of exchangeRows) {
  const c = normaliseTicker(row.Code);
  if (c) allCodes.add(c);
}

const eligible    = new Map();   // ticker -> { name, exchange, isin }
const review      = new Map();
const outOfScope  = new Map();
const dedupedAway = new Map();   // loser -> { keptAs, isin }
const byIsin      = new Map();
const excluded    = {};
const isinDupes   = [];
const badIsins    = [];

for (const row of exchangeRows) {
  const verdict = classifyRow(row);
  const code = normaliseTicker(row.Code);
  const nameRaw = typeof row.Name === 'string' ? row.Name.trim() : '';
  const name = nameRaw && nameRaw !== code ? nameRaw : null;
  const exch = typeof row.Exchange === 'string' ? row.Exchange.trim() : null;
  const isin = typeof row.Isin === 'string' && row.Isin.trim() ? row.Isin.trim() : null;

  if (verdict.outOfScope) {
    outOfScope.set(code, { name, exchange: exch, reason: verdict.reason });
    excluded[verdict.reason] = (excluded[verdict.reason] || 0) + 1;
    continue;
  }
  if (verdict.review) {
    review.set(code, { name, exchange: exch, isin, reason: verdict.reason });
    continue;
  }
  if (!verdict.keep) {
    excluded[verdict.reason] = (excluded[verdict.reason] || 0) + 1;
    continue;
  }

  if (isin && byIsin.has(isin)) {
    const incumbent = byIsin.get(isin);

    if (!sameSecurity(code, incumbent)) {
      // Unrelated companies sharing a vendor ISIN. Keep both; collapsing them
      // silently deletes a live listing.
      badIsins.push(`${isin}: ${incumbent} / ${code} -> BAD VENDOR ISIN, both kept`);
    } else {
      const preferIncoming =
        (mine.has(code) && !mine.has(incumbent)) ||
        (!mine.has(incumbent) && code.includes('-') && !incumbent.includes('-'));

      isinDupes.push(`${isin}: ${incumbent} / ${code} -> kept ${preferIncoming ? code : incumbent}`);

      if (preferIncoming) {
        eligible.delete(incumbent);
        dedupedAway.set(incumbent, { keptAs: code, isin });
      } else {
        dedupedAway.set(code, { keptAs: incumbent, isin });
        continue;
      }
    }
  }

  eligible.set(code, { name, exchange: exch, isin });
  if (isin && !byIsin.has(isin)) byIsin.set(isin, code);
}

// -- Diff --------------------------------------------------------------------
const toAdd      = [...eligible.keys()].filter((t) => !mine.has(t)).sort();
const cleanup    = [];
const held       = [];
const seen       = [];
const miss       = [];
const delist     = [];
const parked     = [];
const reviewMine = [];

for (const [ticker, missCount] of [...mine.entries()].sort()) {
  // Present in some form: clear any accumulated misses.
  if (eligible.has(ticker) || review.has(ticker) || outOfScope.has(ticker)) {
    if (missCount > 0) seen.push(ticker);
    if (outOfScope.has(ticker)) {
      const meta = outOfScope.get(ticker);
      parked.push({ ticker, reason: meta.reason, name: meta.name, exchange: meta.exchange });
    }
    continue;
  }

  // Incomplete pull: for a ticker that's ABSENT we can't tell "delisted" from
  // "its venue didn't return this run". Defer — never move a counter or delete
  // on a partial feed. ADDs from healthy venues (below) are unaffected.
  if (!feedComplete) { held.push(ticker); continue; }

  // Deduped, not absent. Never a delisting candidate.
  if (dedupedAway.has(ticker)) {
    const meta = dedupedAway.get(ticker);
    cleanup.push({ ticker, reason: `duplicate_isin_of_${meta.keptAs}` });
    continue;
  }

  // Junk by construction — no waiting period needed.
  const byCode = classifyCode(ticker);
  if (!byCode.keep && !byCode.review) {
    cleanup.push({ ticker, reason: byCode.reason });
    continue;
  }

  const UNCONDITIONAL_DERIV = /^[A-Z]{2,4}WW$/;
  if (UNCONDITIONAL_DERIV.test(ticker)) {
    cleanup.push({ ticker, reason: 'warrant_ww_suffix' });
    continue;
  }

  const deriv = derivativeOf(ticker, allCodes);
  if (deriv) {
    cleanup.push({ ticker, reason: deriv });
    continue;
  }
  if (byCode.review) {
    reviewMine.push({ ticker, reason: byCode.reason });
    continue;
  }

  // Looks like real common stock, absent from the entire feed.
  const next = missCount + 1;
  if (next >= MISS_THRESHOLD) delist.push({ ticker, misses: next });
  else miss.push({ ticker, misses: next });
}

// -- Floor: threshold-crossers only ------------------------------------------
const delistPct = 100 * delist.length / mine.size;
if (delist.length > MAX_DELISTS_ABS || delistPct > MAX_DELISTS_PCT) {
  throw new Error(
    `${delist.length} of ${mine.size} (${delistPct.toFixed(2)}%) have been ` +
    `absent from the entire feed for ${MISS_THRESHOLD}+ consecutive runs — ` +
    `above the ${MAX_DELISTS_ABS} / ${MAX_DELISTS_PCT}% floor. Sustained ` +
    `absence at this scale means a venue dropped out of the pull, not that ` +
    `these delisted. Check rows_by_exchange first. ` +
    `First 20: ${delist.slice(0, 20).map((d) => d.ticker).join(', ')}. ` +
    `(Separately: ${cleanup.length} CLEANUP, ${miss.length} MISS, ` +
    `${parked.length} OUT_OF_SCOPE, ${reviewMine.length} REVIEW.)`
  );
}

// -- Emit --------------------------------------------------------------------
const out = [];
const stamp = new Date().toISOString();

const push = (action, ticker, meta = {}) => out.push({
  json: {
    action,
    // Factual: is this ticker absent from my universe table right now?
    // True for ADD and for every REVIEW row I don't already hold.
    missingFromMyUniverse: !mine.has(ticker),
    // Routing: should this go to the ingest sub-workflow? ADD only.
    // REVIEW rows are missing too, but deliberately not auto-ingested.
    routeToAdd: action === 'ADD',
    ticker,
    name: meta.name ?? null,
    exchange: meta.exchange ?? null,
    isin: meta.isin ?? null,
    drop_reason: meta.reason ?? null,
    miss_count: meta.misses ?? null,
    as_of: stamp,
  },
});

for (const t of toAdd)          push('ADD', t, eligible.get(t));
for (const r of cleanup)        push('CLEANUP', r.ticker, r);
for (const t of seen)           push('SEEN', t);
for (const r of miss)           push('MISS', r.ticker, { ...r, reason: 'absent_from_feed' });
for (const r of delist)         push('DELIST', r.ticker, { ...r, reason: 'absent_sustained' });
for (const r of parked)         push('OUT_OF_SCOPE', r.ticker, r);
for (const r of reviewMine)     push('REVIEW', r.ticker, r);
for (const [t, meta] of review) if (!mine.has(t)) push('REVIEW', t, meta);

const tally = (arr, key) => JSON.stringify(
  arr.reduce((a, r) => { a[r[key]] = (a[r[key]] || 0) + 1; return a; }, {})
);

out.push({
  json: {
    action: 'SUMMARY',
    missingFromMyUniverse: false,
    exchange_rows_raw: exchangeRows.length,
    exchange_eligible: eligible.size,
    universe_size: mine.size,
    adds: toAdd.length,
    cleanups: cleanup.length,
    seen_again: seen.length,
    misses: miss.length,
    delists: delist.length,
    out_of_scope: parked.length,
    reviews: reviewMine.length + [...review.keys()].filter((t) => !mine.has(t)).length,
    // JSON strings, not arrays — n8n/jsonb rejects top-level arrays
    rows_by_exchange: JSON.stringify(seenByExchange),
    excluded_by_reason: JSON.stringify(excluded),
    cleanup_by_reason: tally(cleanup, 'reason'),
    parked_by_exchange: tally(parked, 'reason'),
    review_by_reason: tally(reviewMine, 'reason'),
    miss_sample: JSON.stringify(miss.slice(0, 100)),
    delist_sample: JSON.stringify(delist.slice(0, 50)),
    isin_duplicates: JSON.stringify(isinDupes.slice(0, 50)),
    bad_vendor_isins: JSON.stringify(badIsins.slice(0, 50)),
    as_of: stamp,
    feed_complete: feedComplete,
    shortfalls: JSON.stringify(shortfalls),
    held_incomplete_feed: held.length,
  },
});

return out;

// Flatten the EODHD earnings calendar to one row per (ticker, exchange, report_date).
//
// DEDUPE ON (ticker, exchange, report_date): a 21-day window can legitimately
// contain two announcements for the same company, AND the same symbol can exist
// on multiple exchanges (e.g. DGNOF.US vs a .LSE listing). Keying on ticker
// alone — or even (ticker, report_date) — lets an LSE row overwrite the US row
// for an overlapping symbol. The exchange is part of the identity.
//
// LAST WINS on an exact duplicate key: a later entry in the payload is the more
// recent statement of the same event.

// Exchanges to keep. Set to null to accept every exchange the feed returns.
const ALLOWED_EXCHANGES = new Set(['US'/*, 'LSE'*/]);

const seen = new Map();
let scanned = 0, skippedExchange = 0, malformed = 0;

for (const item of $input.all()) {
  const list = item?.json?.earnings;
  if (!Array.isArray(list)) continue;

  for (const earning of list) {
    scanned++;
    const code = earning?.code;
    if (typeof code !== 'string') { malformed++; continue; }

    // Split on the LAST dot: a ticker may contain dots, the exchange suffix never does.
    const dot = code.lastIndexOf('.');
    if (dot <= 0) { malformed++; continue; }

    const ticker     = code.slice(0, dot).trim().toUpperCase();
    const exchange   = code.slice(dot + 1).trim().toUpperCase();
    const reportDate = earning?.report_date;

    if (!ticker || !exchange || !reportDate) { malformed++; continue; }
    if (ALLOWED_EXCHANGES && !ALLOWED_EXCHANGES.has(exchange)) { skippedExchange++; continue; }

    seen.set(`${ticker}|${exchange}|${reportDate}`, {
      ...earning,
      ticker,
      exchange,
      code: undefined,
    });
  }
}

const output = [...seen.values()].map(({ code, ...rest }) => ({ json: rest }));

// Sorted nearest-first so a truncated load still holds the most urgent dates.
output.sort((a, b) => String(a.json.report_date).localeCompare(String(b.json.report_date)));

if (output.length) {
  output[0].json._diag = {
    scanned,
    emitted: output.length,
    duplicates_removed: scanned - skippedExchange - malformed - output.length,
    exchange_skipped: skippedExchange,
    malformed_skipped: malformed,
  };
}

return output;
